import * as THREE from './vendor/three.module.js';
import { BUILDINGS, STYLES, sanitizeDesign, designCost, getBuilding } from './catalog.js?v=20261110-traffic2';
import { createDesignedBuilding, disposeUnusedDesignerMaterials } from './building-designer.js?v=20261110-traffic2';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const CATEGORIES={residential:'住宅',commercial:'商业',park:'公园',public:'公共',blueprints:'蓝图'};
const symbol={residential:'▥',commercial:'▦',park:'♧',public:'✚'};
const BLUEPRINT_KEY='pixel-bay-blueprints-v1';

export class BuildStudio {
 constructor({scene,onSelect,onMessage}){
  this.worldScene=scene;this.onSelect=onSelect;this.onMessage=onMessage;this.design=sanitizeDesign({catalogId:'villa'});this.category='residential';this.blueprints=[];this.opened=false;
  try{const arr=JSON.parse(localStorage.getItem(BLUEPRINT_KEY)||'[]');if(Array.isArray(arr))this.blueprints=arr.slice(0,40).flatMap(b=>{try{return[{name:String(b.name||'我的建筑').slice(0,30),design:sanitizeDesign(b.design)}]}catch{return[]}})}catch{}
  this.drawer=document.createElement('aside');this.drawer.className='catalog-drawer panel hidden';this.drawer.id='catalog-drawer';this.drawer.setAttribute('aria-label','建筑目录');document.body.append(this.drawer);
  this.dialog=document.createElement('dialog');this.dialog.id='building-studio';this.dialog.className='building-studio';document.body.append(this.dialog);
  this.dialog.addEventListener('close',()=>{this.opened=false;this.onPause?.(false)});
  this.dialog.addEventListener('keydown',e=>{e.stopPropagation();});
  this.renderCatalog();this.makeDialog();
  this.previewResize=new ResizeObserver(()=>{if(this.opened)this.framePreview();});this.previewResize.observe(this.dialog.querySelector('#studio-preview'));
 }
 toggleCatalog(category){if(category){this.category=category;this.renderCatalog()}this.drawer.classList.toggle('hidden');}
 closeCatalog(){this.drawer.classList.add('hidden')}
 renderCatalog(){
  const items=this.category==='blueprints'?this.blueprints.map((b,i)=>({id:String(i),name:b.name,design:b.design,...BUILDINGS[b.design.catalogId]})):Object.values(BUILDINGS).filter(b=>b.category===this.category);
  this.drawer.innerHTML=`<div class="catalog-heading"><div><small>CITY BUILDING LIBRARY</small><h2>每一栋，都有自己的生活。</h2></div><button id="catalog-close" aria-label="关闭建筑目录">×</button></div><div class="catalog-tabs">${Object.entries(CATEGORIES).map(([k,v])=>`<button data-category="${k}" class="${k===this.category?'active':''}">${v}${k==='blueprints'?`<small>${this.blueprints.length}</small>`:''}</button>`).join('')}</div><div class="catalog-grid">${items.length?items.map((b,i)=>{const d=b.design||sanitizeDesign({catalogId:b.id});const meta=getBuilding({type:BUILDINGS[d.catalogId].baseType,level:1,design:d});return `<button class="building-card" data-building="${this.category==='blueprints'?i:b.id}"><div class="building-card-art category-${meta.category}"><i>${symbol[meta.category]}</i><span>${meta.category==='public'?'公共服务':`${d.floors}F`}</span></div><b>${esc(this.category==='blueprints'?this.blueprints[i].name:b.name)}</b><small>${esc(meta.description)}</small><div><span>₵ ${designCost(d).toLocaleString()}</span><em>${meta.category==='public'&&meta.radius?`${meta.radius} 格服务`:meta.capacity?`${meta.capacity} 人`:meta.jobs?`${meta.jobs} 岗位`:meta.radius?`${meta.radius} 格服务`:'宜居提升'}</em></div></button>`}).join(''):'<div class="empty-blueprints">还没有蓝图。<br>在 DIY 工坊保存你的第一栋建筑。</div>'}</div><div class="catalog-footer"><button id="open-designer">打开 DIY 建筑工坊 ↗</button><span>选一栋建筑，再点击地图放置</span></div>`;
  this.drawer.querySelector('#catalog-close').onclick=()=>this.closeCatalog();
  this.drawer.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{this.category=b.dataset.category;this.renderCatalog()});
  this.drawer.querySelectorAll('[data-building]').forEach(b=>b.onclick=()=>{this.design=this.category==='blueprints'?clone(this.blueprints[Number(b.dataset.building)].design):sanitizeDesign({catalogId:b.dataset.building});this.onSelect(clone(this.design));this.onMessage(`已选择 ${BUILDINGS[this.design.catalogId].name} · ${this.design.width}×${this.design.depth} 格`);this.closeCatalog();});
  this.drawer.querySelector('#open-designer').onclick=()=>this.open();
 }
 makeDialog(){
  this.dialog.innerHTML=`<div class="studio-header"><div><small>PIXEL BAY / ARCHITECT STUDIO</small><h2>把你的想象，建成一栋房子。</h2></div><button id="studio-close" aria-label="关闭建筑工坊">×</button></div><div class="studio-layout"><div class="studio-preview-wrap"><div id="studio-preview"></div><div class="studio-preview-caption"><b id="studio-name"></b><span id="studio-dimensions"></span></div><button id="studio-rotate" title="旋转建筑">↻ 旋转朝向</button><div class="studio-price"><span>预计建造费用</span><strong id="studio-cost"></strong></div></div><div class="studio-controls"><label>建筑类型<select id="design-kind">${Object.values(BUILDINGS).map(b=>`<option value="${b.id}">${CATEGORIES[b.category]} / ${b.name}</option>`).join('')}</select></label><div class="studio-field-row"><label>建筑风格<select id="design-style">${STYLES.map(s=>`<option value="${s.id}">${s.label}</option>`).join('')}</select></label><label>墙面颜色<input type="color" id="design-color" value="#b5b0a2"></label></div><label for="design-floors">楼层 <span id="floor-value"></span><input type="range" id="design-floors" min="1" max="12" step="1"></label><div class="studio-field-row"><label>占地宽度<select id="design-width"><option>1</option><option>2</option><option>3</option></select></label><label>占地深度<select id="design-depth"><option>1</option><option>2</option><option>3</option></select></label><label>屋顶<select id="design-roof"><option value="flat">平屋顶</option><option value="pitched">坡屋顶</option><option value="garden">空中花园</option></select></label></div><div class="studio-components"><span>模块化附属组件</span><div>${[['garden','庭院绿化'],['wall','围墙'],['garage','车库'],['pool','泳池'],['terrace','露台'],['solar','太阳能']].map(([k,v])=>`<label><input type="checkbox" data-component="${k}">${v}</label>`).join('')}</div></div><p class="studio-note">占地需要整片空地，并与城市道路相连。外观与尺寸会影响建造成本，建筑用途决定经营功能。</p><div class="blueprint-save"><input id="blueprint-name" maxlength="30" placeholder="给蓝图起个名字" aria-label="蓝图名称"><button id="save-blueprint">保存蓝图</button></div><div class="blueprint-files"><button id="export-blueprint">导出蓝图 JSON</button><button id="import-blueprint">导入蓝图 JSON</button><input type="file" id="blueprint-file" accept="application/json,.json" hidden></div></div></div><div class="studio-footer"><span id="studio-summary"></span><button class="primary-button" id="place-design">使用这份设计 →</button></div>`;
  this.dialog.querySelector('#studio-close').onclick=()=>this.dialog.close();
  this.dialog.querySelector('#design-kind').onchange=e=>{this.design=sanitizeDesign({catalogId:e.target.value,style:this.design.style,color:this.design.color});this.syncFields();this.renderPreview()};
  const bind=(id,key,convert=x=>x)=>this.dialog.querySelector(id).oninput=e=>{this.design[key]=convert(e.target.value);this.design=sanitizeDesign(this.design);this.renderPreview()};
  bind('#design-style','style');bind('#design-color','color');bind('#design-floors','floors',Number);bind('#design-width','width',Number);bind('#design-depth','depth',Number);bind('#design-roof','roof');
  this.dialog.querySelectorAll('[data-component]').forEach(b=>b.onchange=()=>{this.design.components[b.dataset.component]=b.checked;this.renderPreview()});
  this.dialog.querySelector('#studio-rotate').onclick=()=>{this.design.rotation=(this.design.rotation+1)%4;this.renderPreview()};
  this.dialog.querySelector('#place-design').onclick=()=>{this.onSelect(clone(this.design));this.dialog.close();this.closeCatalog();this.onMessage('设计已准备好，点击沿路空地放置。')};
  this.dialog.querySelector('#save-blueprint').onclick=()=>{const name=this.dialog.querySelector('#blueprint-name').value.trim()||`${BUILDINGS[this.design.catalogId].name} · ${STYLES.find(s=>s.id===this.design.style)?.label||''}`;const idx=this.blueprints.findIndex(b=>b.name===name);const item={name:name.slice(0,30),design:clone(this.design)};if(idx>=0)this.blueprints[idx]=item;else this.blueprints.unshift(item);this.blueprints=this.blueprints.slice(0,40);try{localStorage.setItem(BLUEPRINT_KEY,JSON.stringify(this.blueprints));this.onMessage(`蓝图「${name}」已保存`);this.renderCatalog()}catch{this.onMessage('浏览器存储已满，可导出蓝图保留。',true)}};
  this.dialog.querySelector('#export-blueprint').onclick=()=>downloadJSON({format:'pixel-bay-blueprint',version:1,name:this.dialog.querySelector('#blueprint-name').value.trim()||BUILDINGS[this.design.catalogId].name,design:this.design},'pixel-bay-blueprint.json');
  const file=this.dialog.querySelector('#blueprint-file');this.dialog.querySelector('#import-blueprint').onclick=()=>file.click();file.onchange=async()=>{const selected=file.files?.[0];file.value='';if(!selected)return;try{if(selected.size>100000)throw new Error('蓝图文件过大');const data=JSON.parse(await selected.text());if(data.format!=='pixel-bay-blueprint'||data.version!==1||!Object.hasOwn(BUILDINGS,data.design?.catalogId))throw new Error('不是兼容的方寸湾蓝图');this.design=sanitizeDesign(data.design);this.dialog.querySelector('#blueprint-name').value=String(data.name||'导入蓝图').slice(0,30);this.syncFields();this.renderPreview();this.onMessage('蓝图已导入，可继续修改或保存。')}catch(e){this.onMessage(e.message||'导入失败',true)}};
 }
 open(design=null){if(design)this.design=sanitizeDesign(design);this.closeCatalog();this.syncFields();this.opened=true;this.dialog.showModal();this.onPause?.(true);this.renderPreview();}
 syncFields(){const d=this.design;for(const k of ['style','color','floors','width','depth','roof'])this.dialog.querySelector('#design-'+k).value=d[k];this.dialog.querySelector('#design-kind').value=d.catalogId;this.dialog.querySelectorAll('[data-component]').forEach(b=>b.checked=!!d.components[b.dataset.component]);}
 renderPreview(){
  const d=this.design,m=BUILDINGS[d.catalogId];this.dialog.querySelector('#floor-value').textContent=`${d.floors} 层`;this.dialog.querySelector('#studio-name').textContent=m.name;this.dialog.querySelector('#studio-dimensions').textContent=`${d.rotation%2?d.depth:d.width} × ${d.rotation%2?d.width:d.depth} 街区 · ${d.floors}F`;this.dialog.querySelector('#studio-cost').textContent='₵ '+designCost(d).toLocaleString();this.dialog.querySelector('#studio-summary').textContent=`${m.jobs?`${m.jobs} 基础岗位 · `:''}${m.capacity?`${m.capacity} 基础容量 · `:''}用途：${m.description}`;
  if(!this.opened)return;
  if(!this.previewRenderer){this.previewRenderer=new THREE.WebGLRenderer({antialias:true,alpha:true});this.previewRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));this.previewRenderer.outputColorSpace=THREE.SRGBColorSpace;this.previewRenderer.toneMapping=THREE.ACESFilmicToneMapping;this.previewRenderer.toneMappingExposure=1.2;this.previewScene=new THREE.Scene();this.previewScene.add(new THREE.HemisphereLight('#eaf3ff','#7c795e',2));const light=new THREE.DirectionalLight('#ffe7c5',3);light.position.set(-3,5,4);this.previewScene.add(light);this.previewCamera=new THREE.PerspectiveCamera(35,1,.1,100);this.dialog.querySelector('#studio-preview').append(this.previewRenderer.domElement);}
  if(this.previewModel){this.previewScene.remove(this.previewModel);this.previewModel.traverse(o=>{if(o.isInstancedMesh)o.dispose();});}
  this.previewModel=createDesignedBuilding(d,1,3);this.previewScene.add(this.previewModel);disposeUnusedDesignerMaterials([this.worldScene,this.previewScene]);this.previewScene.environment=this.worldScene.environment;this.previewScene.environmentIntensity=.4;
  this.framePreview();
 }
 framePreview(){
  if(!this.opened||!this.previewModel||!this.previewRenderer)return;
  const bounds=new THREE.Box3().setFromObject(this.previewModel),center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());const el=this.dialog.querySelector('#studio-preview'),w=el.clientWidth||310,h=el.clientHeight||370;this.previewRenderer.setSize(w,h);this.previewCamera.aspect=w/h;this.previewCamera.updateProjectionMatrix();const radius=size.length()/2,halfFov=Math.min(THREE.MathUtils.degToRad(17.5),Math.atan(Math.tan(THREE.MathUtils.degToRad(17.5))*this.previewCamera.aspect));const distance=radius/Math.sin(halfFov)*1.08;this.previewCamera.position.copy(new THREE.Vector3(.8,.55,.9).normalize().multiplyScalar(distance).add(center));this.previewCamera.lookAt(center);this.previewRenderer.render(this.previewScene,this.previewCamera);
 }
}
export function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
